namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public static int Calculate(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(CapCents, subtotalCents * RatePercent(tier) / 100);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier)),
    };
}
EOF
cat > CheckoutPricing.Domain/PromoCodePolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public static int Calculate(string? code, int subtotalCents, int loyaltyDiscountCents)
    {
        if (string.Equals(code, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return Welcome5Cents;
        }

        if (string.Equals(code, "SUMMER10", StringComparison.OrdinalIgnoreCase))
        {
            return Math.Min(Summer10CapCents, (subtotalCents - loyaltyDiscountCents) / 10);
        }

        return 0;
    }
}
EOF
cat > CheckoutPricing.Domain/ShippingFeePolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int FreeStandardFromCents = 5_000;
    private const int ExpressFeeCents = 990;

    public static int Standard(int payableTotalCents, LoyaltyTier tier) =>
        tier is LoyaltyTier.Gold or LoyaltyTier.Platinum || payableTotalCents >= FreeStandardFromCents
            ? 0
            : StandardFeeCents;

    public static int Express(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;
}
EOF
python3 - <<'EOF'
import re
p='CheckoutPricing.Application/CalculateLoyaltyDiscount.cs'
s=open(p).read()
s=s[:s.index('    public LoyaltyDiscountQuote Handle')]+'''    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var loyaltyCents = LoyaltyDiscountPolicy.Calculate(query.SubtotalCents, query.LoyaltyTier);
        var promoCents = PromoCodePolicy.Calculate(query.PromoCode, query.SubtotalCents, loyaltyCents);
        var discountCents = Math.Min(query.SubtotalCents, loyaltyCents + promoCents);
        return new(query.SubtotalCents, discountCents, query.SubtotalCents - discountCents, query.LoyaltyTier);
    }
}
'''
open(p,'w').write(s)
p='CheckoutPricing.Application/CalculateShippingFee.cs'
s=open(p).read()
s=s.replace('public int Handle(CalculateShippingFeeQuery query) => 0;','''public int Handle(CalculateShippingFeeQuery query) =>
        query.Express
            ? ShippingFeePolicy.Express(query.LoyaltyTier)
            : ShippingFeePolicy.Standard(query.PayableTotalCents, query.LoyaltyTier);''')
open(p,'w').write(s)
p='CheckoutPricing.Application/QuoteCheckout.cs'
s=open(p).read()
s=s.replace('    public CheckoutQuote Handle(QuoteCheckoutQuery query) => new(0, 0, 0);','''    public CheckoutQuote Handle(QuoteCheckoutQuery query)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(
            new CalculateLoyaltyDiscountQuery(query.SubtotalCents, query.LoyaltyTier, query.PromoCode));
        var shippingCents = new CalculateShippingFee().Handle(
            new CalculateShippingFeeQuery(quote.TotalCents, query.LoyaltyTier, query.Express));
        return new(quote.TotalCents, shippingCents, quote.TotalCents + shippingCents);
    }''')
open(p,'w').write(s)
EOF
